import de.rub.nds.tlsattacker.core.quic.constants.QuicFrameType;
import de.rub.nds.tlsattacker.core.quic.frame.ConnectionCloseFrame;
import java.io.InputStream;
import org.apache.logging.log4j.LogManager;
